//! Reading Geometry Dash state out of frames.

mod bar;
mod calibrate;
mod glyph;
mod percent;
mod templates;
mod text;

pub use bar::{candidates, BarRegion};
pub use calibrate::{Calibration, Calibrator};
pub use glyph::{is_decimal_point, GlyphBitmap, TemplateSet, GLYPH_H, GLYPH_W};
pub use percent::{read_percentage, Reading};
pub use text::{segment, GlyphBox, TextRegion};

/// Template set shipped with the app.
///
/// Kept out of `templates.rs`, which is regenerated by the `mktemplates`
/// example and holds only data.
#[must_use]
pub fn builtin() -> TemplateSet {
    let mut set = TemplateSet::new();
    for &(label, bits) in templates::TEMPLATES {
        if let Some(bitmap) = GlyphBitmap::from_bits(bits) {
            set.insert(label, bitmap);
        }
    }
    set
}
